import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import axiosInstance from '../../core/api/axiosConfig';
import {
  Box, Typography, Paper, Table, TableBody, TableCell, TableContainer,
  TableHead, TableRow, IconButton, Chip, CircularProgress, TextField,
  InputAdornment, Button, Dialog, DialogTitle, DialogContent, DialogActions,
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import SearchIcon from '@mui/icons-material/Search';
import { toJalali } from '../../core/utils/dateUtils';
import { toPersianDigits } from '../../core/utils/numberUtils';
import { PRIORITY_LABELS, PRIORITY_COLORS } from './config';

/* Generic CRUD list + dialog for correspondences.
 * Props:
 *  - endpoint: API endpoint (e.g. '/incoming-letters/')
 *  - title: header label (e.g. 'نامه‌های وارده')
 *  - color: accent color
 *  - searchPlaceholder
 *  - fields: array of { key, label } for form
 *  - columns: array of { key, label, render? } for table
 *  - searchFields (list to pass as ?search=) - uses DRF search query param name
 */
export const CorrespondenceCRUD = ({
  endpoint, title, color, searchPlaceholder, fields, columns, defaultForm = {},
}) => {
  const queryClient = useQueryClient();
  const [search, setSearch] = useState('');
  const [open, setOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState({});

  const { data, isLoading } = useQuery({
    queryKey: [endpoint],
    queryFn: () => axiosInstance.get(endpoint).then(r => r.data.results || r.data),
  });

  const saveMutation = useMutation({
    mutationFn: (payload) => editing
      ? axiosInstance.patch(`${endpoint}${editing.id}/`, payload)
      : axiosInstance.post(endpoint, payload),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: [endpoint] });
      setOpen(false); setEditing(null); setForm({});
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => axiosInstance.delete(`${endpoint}${id}/`),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: [endpoint] }),
  });

  const items = Array.isArray(data) ? data : data?.results || [];
  const filtered = search.trim()
    ? items.filter(it => fields.some(f => String(it[f.key] || '').toLowerCase().includes(search.toLowerCase())))
    : items;

  const openNew = () => { setEditing(null); setForm({ ...defaultForm }); setOpen(true); };
  const openEdit = (it) => { setEditing(it); setForm({ ...it }); setOpen(true); };

  const renderValue = (it, col) => {
    if (col.render) return col.render(it);
    const v = it[col.key];
    if (col.key === 'priority') {
      return <Chip size="small" label={PRIORITY_LABELS[v] || v} sx={{ color: PRIORITY_COLORS[v], borderColor: PRIORITY_COLORS[v] }} variant="outlined" />;
    }
    if (col.key === 'date' || col.key.endsWith('_date')) return toJalali(v);
    if (col.key === 'number' || col.key === 'code') return toPersianDigits(v);
    return v || '—';
  };

  return (
    <Box>
      {/* Toolbar */}
      <Box sx={{ display: 'flex', gap: 1.5, alignItems: 'center', mb: 2, flexWrap: 'wrap' }}>
        <TextField
          size="small" placeholder={searchPlaceholder}
          value={search} onChange={e => setSearch(e.target.value)}
          InputProps={{ startAdornment: <InputAdornment position="start"><SearchIcon fontSize="small" /></InputAdornment> }}
          sx={{ flex: 1, minWidth: 220 }}
        />
        <Button variant="contained" startIcon={<AddIcon />} onClick={openNew} sx={{ bgcolor: color, '&:hover': { bgcolor: color } }}>
          افزودن
        </Button>
      </Box>

      <TableContainer component={Paper} variant="outlined" sx={{ borderRadius: 2 }}>
        {isLoading ? (
          <Box sx={{ p: 4, textAlign: 'center' }}><CircularProgress size={24} /></Box>
        ) : filtered.length === 0 ? (
          <Box sx={{ p: 4, textAlign: 'center' }}><Typography color="textSecondary">موردی یافت نشد</Typography></Box>
        ) : (
          <Table size="small">
            <TableHead>
              <TableRow>
                {columns.map(c => <TableCell key={c.key} sx={{ fontWeight: 700 }}>{c.label}</TableCell>)}
                <TableCell width={90} sx={{ fontWeight: 700 }}>عملیات</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filtered.map((it, i) => (
                <TableRow key={it.id} hover>
                  {columns.map(c => <TableCell key={c.key}>{renderValue(it, c)}</TableCell>)}
                  <TableCell>
                    <IconButton size="small" onClick={() => openEdit(it)}><EditIcon fontSize="small" /></IconButton>
                    <IconButton size="small" color="error" onClick={() => deleteMutation.mutate(it.id)}><DeleteIcon fontSize="small" /></IconButton>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </TableContainer>

      {/* Dialog */}
      <Dialog open={open} onClose={() => setOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle sx={{ color }}>{editing ? `ویرایش ${title}` : `افزودن ${title}`}</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, mt: 1 }}>
            {fields.map(f => f.render ? React.cloneElement(f.render(form, setForm), { key: f.key })
              : (
                <TextField key={f.key} fullWidth size="small" label={f.label}
                  type={f.type || 'text'} value={form[f.key] || ''}
                  onChange={e => setForm(p => ({ ...p, [f.key]: e.target.value }))}
                  multiline={f.multiline} rows={f.multiline ? 3 : 1}
                  InputLabelProps={f.type === 'date' ? { shrink: true } : {}}
                  required={f.required} />
              ))}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpen(false)}>انصراف</Button>
          <Button variant="contained" onClick={() => saveMutation.mutate(form)} disabled={saveMutation.isLoading}
            sx={{ bgcolor: color, '&:hover': { bgcolor: color } }}>
            {saveMutation.isLoading ? <CircularProgress size={20} /> : 'ذخیره'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default CorrespondenceCRUD;
